<?php $pageTitle='Kanban board'; $activePage='tasks'; require_once __DIR__.'/../includes/header.php'; require_permission('manage_tasks'); $columns=['Backlog','To Do','In Progress','Code Review','Testing','Done']; $tasks=$pdo->query("SELECT t.*,p.name project_name FROM tasks t JOIN projects p ON p.id=t.project_id ORDER BY t.due_date")->fetchAll(); ?><div class="d-flex justify-content-between align-items-end mb-4"><div><span class="section-kicker">Execution view</span><h2 class="mt-2">Kanban board</h2><p class="text-muted mb-0">A clear view of flow, blockers, and what ships next.</p></div><a href="<?= url('tasks/create.php') ?>" class="btn btn-primary"><i class="bi bi-plus-lg me-2"></i>Add task</a></div><div class="kanban-board"><?php foreach($columns as $column): $columnTasks=array_filter($tasks,fn($task)=>$task['status']===$column); ?><section class="kanban-column"><h4><?= e($column) ?><span class="kanban-count"><?= count($columnTasks) ?></span></h4><?php foreach($columnTasks as $task): ?><article class="kanban-card"><strong><?= e($task['title']) ?></strong><div class="card-meta"><span class="status-badge status-<?= strtolower($task['priority']) ?>"><?= e($task['priority']) ?></span><small><i class="bi bi-calendar3 me-1"></i><?= e(date('M d',strtotime($task['due_date']))) ?></small></div><small class="d-block mt-3"><i class="bi bi-briefcase me-1"></i><?= e($task['project_name']) ?></small></article><?php endforeach; ?></section><?php endforeach; ?></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
